const root=document.querySelector('#manutencao-view');let rows=[],view='kanban',selectedId=null;
const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const sts=['Solicitado','Em cotação','Aguardando aprovação','Pedido emitido','Aguardando entrega','Recebido / Concluído','Cancelado','Duplicado'];
const flow=['Solicitado','Em cotação','Aguardando aprovação','Pedido emitido','Aguardando entrega','Recebido / Concluído'];
const lanes=[['Solicitado',['Solicitado']],['Em cotação',['Em cotação']],['Aguardando aprovação',['Aguardando aprovação']],['Pedido emitido',['Pedido emitido']],['Aguardando entrega',['Aguardando entrega']],['Concluído / Cancelado',['Recebido / Concluído','Cancelado','Duplicado']]];
const opt=(a,v)=>a.map(x=>'<option'+(x===v?' selected':'')+'>'+e(x)+'</option>').join('');
const closed=r=>['Recebido / Concluído','Cancelado','Duplicado'].includes(r.status);
const d=v=>v?v.split('-').reverse().join('/'):'—';
const parsed=r=>{try{return JSON.parse(r.quotesJson||'[]')}catch{return []}};
const meta=r=>parsed(r).find(x=>x&&x.kind==='commercial')||{};
const quotes=r=>parsed(r).filter(x=>x&&x.kind==='quote');
const money=v=>{const n=quoteNumber(v);return n!=null&&n!==0?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n):'—'};
const dueClass=r=>{if(!r.neededDate||closed(r))return'';const a=new Date(r.neededDate+'T12:00:00'),b=new Date();b.setHours(12,0,0,0);const n=Math.ceil((a-b)/86400000);return n<0?'late':n<=3?'soon':''};
const nextStatus=r=>{const i=flow.indexOf(r.status);return i>=0&&i<flow.length-1?flow[i+1]:null};
async function saveRow(r,patch){const v={...r,...patch};delete v.history;delete v.createdAt;delete v.updatedAt;delete v.number;const z=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)}),j=await z.json();if(!z.ok)throw Error(j.error||'Erro ao salvar');return j}
async function load(){const x=await fetch('/api/maintenance');rows=(await x.json()).requests||[];render()}
function quoteSummary(r){const q=quotes(r);if(!q.length)return'';const vals=q.map(x=>Number(String(x.amount||'').replace(',','.'))).filter(Number.isFinite),min=vals.length?Math.min(...vals):null;return '<div class="mn-quote-summary"><b>Cotações</b><span>'+q.length+' fornecedor'+(q.length===1?'':'es')+'</span>'+(min!=null?'<strong>Menor valor: '+money(min)+'</strong>':'')+'</div>'}
function card(r){const due=dueClass(r),n=nextStatus(r);return '<article class="maintenance-card '+(r.priority==='Urgente'?'urgent ':'')+due+'" data-card="'+r.id+'"><div class="maintenance-card-head"><strong>'+e(r.number)+'</strong><div class="mn-card-head-right">'+(r.company?'<span class="mn-company '+e(r.company.toLowerCase())+'">'+e(r.company)+'</span>':'')+'<span class="mn-status '+e(r.status.toLowerCase().replaceAll(' ','-'))+'">'+e(r.status)+'</span></div></div><h4>'+e(r.description)+'</h4><div class="mn-card-info">'+(r.company?'<p class="mn-company-info">🏢 <b>Empresa:</b> '+e(r.company)+'</p>':'')+'<p>♙ <b>Solicitante:</b> '+e(r.requester)+'</p><p>▣ <b>Responsável:</b> '+e(r.buyer||'Não assumido')+'</p><p>◉ <b>Origem:</b> '+e(r.origin)+(r.oc?' · OC '+e(r.oc):'')+'</p><p class="'+due+'">▣ <b>Necessário até:</b> '+d(r.neededDate)+'</p><p>⚖ <b>Quantidade:</b> '+e(r.quantity||'—')+' '+e(r.unit||'')+'</p>'+(r.equipment?'<p>⚙ <b>Equipamento:</b> '+e(r.equipment)+'</p>':'')+(r.supplier?'<p>⌁ <b>Fornecedor:</b> '+e(r.supplier)+'</p>':'')+(money(meta(r).amount)!=='—'?'<p>♧ <b>Valor:</b> '+money(meta(r).amount)+'</p>':'')+(r.systemOrder?'<p>⌘ <b>Pedido:</b> '+e(r.systemOrder)+'</p>':'')+'</div>'+quoteSummary(r)+(r.status==='Aguardando entrega'&&!r.promisedDate?'<p class="maintenance-alert">⚠ Prazo de entrega não informado</p>':'')+'<div class="mn-card-actions"><button title="Visualizar" aria-label="Visualizar" data-eye="'+r.id+'">👁️</button><button title="Editar" aria-label="Editar" data-edit="'+r.id+'">✏️</button><button title="WhatsApp" aria-label="WhatsApp" class="wa" data-wa="'+r.id+'"><svg class="mn-wa-icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2a9.8 9.8 0 0 0-8.5 14.7L2 22l5.4-1.4A10 10 0 1 0 12 2Zm0 18.2c-1.5 0-2.9-.4-4.2-1.1l-.3-.2-3.2.8.9-3.1-.2-.3A8.1 8.1 0 1 1 12 20.2Zm4.5-6.1c-.2-.1-1.4-.7-1.7-.8-.2-.1-.4-.1-.6.1-.2.3-.6.8-.8 1-.1.2-.3.2-.5.1-1.4-.7-2.4-1.3-3.3-2.9-.2-.3.2-.3.7-1.1.1-.2.1-.4 0-.6l-.7-1.7c-.2-.4-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3-.2.3-.9.9-.9 2.2s.9 2.5 1.1 2.7c.1.2 1.8 2.8 4.5 3.9 1.7.7 2.4.8 3.3.7 1-.2 1.4-.7 1.6-1.3.2-.6.2-1.1.1-1.2-.2-.1-.4-.2-.9-.4Z"/></svg></button>'+(n?'<button class="advance" data-advance="'+r.id+'">Avançar →</button>':'')+'</div></article>'}
function render(){const open=rows.filter(r=>!closed(r));root.innerHTML='<div class="mn-title-actions"><div></div><button id="mn" class="mn-new">＋ Nova solicitação</button></div><div class="maintenance-kpis">'+[['▤',rows.filter(r=>r.status==='Solicitado').length,'Solicitado','blue'],['◇',rows.filter(r=>r.status==='Em cotação').length,'Em cotação','orange'],['♙',rows.filter(r=>r.status==='Aguardando aprovação').length,'Aguardando aprovação','green'],['🛒',rows.filter(r=>r.status==='Pedido emitido').length,'Pedido emitido','purple'],['▣',rows.filter(r=>r.status==='Aguardando entrega').length,'Aguardando entrega','red'],['✓',rows.filter(closed).length,'Concluído / Cancelado','green']].map(x=>'<div class="'+x[3]+'"><i>'+x[0]+'</i><strong>'+x[1]+'</strong><span>'+x[2]+'</span></div>').join('')+'</div><section class="panel maintenance-toolbar"><div class="mn-search">⌕ <input id="ms" placeholder="Buscar material, serviço, OC, pedido, solicitante ou responsável"></div><select id="mstatus"><option value="">Todos os status</option>'+opt(sts,'')+'</select><select id="morigin"><option value="">Todas as origens</option>'+opt(['OC','WhatsApp','Outro'],'')+'</select><div class="maintenance-view"><button data-view="kanban">▥ Kanban</button><button data-view="list">☷ Lista</button></div></section><div id="me"></div><div id="maintenance-content"></div><div id="mn-detail"></div>';document.querySelector('#mn').onclick=()=>form({});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;draw()});['ms','mstatus','morigin'].forEach(id=>document.querySelector('#'+id).oninput=draw);draw()}
function filtered(){const q=document.querySelector('#ms').value.toLowerCase(),s=document.querySelector('#mstatus').value,o=document.querySelector('#morigin').value;return rows.filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!s||r.status===s)&&(!o||r.origin===o))}
function bindActions(box){box.querySelectorAll('[data-open-row]').forEach(tr=>tr.onclick=()=>detail(rows.find(r=>r.id===tr.dataset.openRow)));box.querySelectorAll('[data-eye]').forEach(b=>b.onclick=x=>{x.stopPropagation();detail(rows.find(r=>r.id===b.dataset.eye))});box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=x=>{x.stopPropagation();form(rows.find(r=>r.id===b.dataset.edit))});box.querySelectorAll('[data-wa]').forEach(b=>b.onclick=x=>{x.stopPropagation();whatsapp(rows.find(r=>r.id===b.dataset.wa))});box.querySelectorAll('[data-advance]').forEach(b=>b.onclick=async x=>{x.stopPropagation();const r=rows.find(r=>r.id===b.dataset.advance),n=nextStatus(r);if(!n)return;b.disabled=true;try{await saveRow(r,{status:n});await load()}catch(err){alert(err.message)}})}
function draw(){const list=filtered(),box=document.querySelector('#maintenance-content');if(view==='list'){box.innerHTML='<section class="panel mn-list"><h3>Visualização em lista</h3><div class="table-scroll"><table><thead><tr><th>Código</th><th>Descrição</th><th>Status</th><th>Necessário até</th><th>Solicitante</th><th>Responsável</th><th>Ações</th></tr></thead><tbody>'+list.map(r=>'<tr class="mn-list-row" data-open-row="'+r.id+'" title="Clique para visualizar '+e(r.number)+'"><td><strong>'+e(r.number)+'</strong></td><td>'+e(r.description)+'</td><td>'+e(r.status)+'</td><td>'+d(r.neededDate)+'</td><td>'+e(r.requester)+'</td><td>'+e(r.buyer||'—')+'</td><td><button title="Visualizar" aria-label="Visualizar" data-eye="'+r.id+'">👁️</button> <button title="Editar" aria-label="Editar" data-edit="'+r.id+'">✏️</button> <button title="WhatsApp" aria-label="WhatsApp" class="wa" data-wa="'+r.id+'"><svg class="mn-wa-icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2a9.8 9.8 0 0 0-8.5 14.7L2 22l5.4-1.4A10 10 0 1 0 12 2Zm0 18.2c-1.5 0-2.9-.4-4.2-1.1l-.3-.2-3.2.8.9-3.1-.2-.3A8.1 8.1 0 1 1 12 20.2Zm4.5-6.1c-.2-.1-1.4-.7-1.7-.8-.2-.1-.4-.1-.6.1-.2.3-.6.8-.8 1-.1.2-.3.2-.5.1-1.4-.7-2.4-1.3-3.3-2.9-.2-.3.2-.3.7-1.1.1-.2.1-.4 0-.6l-.7-1.7c-.2-.4-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3-.2.3-.9.9-.9 2.2s.9 2.5 1.1 2.7c.1.2 1.8 2.8 4.5 3.9 1.7.7 2.4.8 3.3.7 1-.2 1.4-.7 1.6-1.3.2-.6.2-1.1.1-1.2-.2-.1-.4-.2-.9-.4Z"/></svg></button></td></tr>').join('')+'</tbody></table></div></section>';bindActions(box)}else{box.innerHTML='<div class="maintenance-board">'+lanes.map(l=>{const a=list.filter(r=>l[1].includes(r.status));return '<section class="maintenance-lane"><header><strong>'+l[0]+'</strong><span>'+a.length+'</span></header><div>'+((a.length?a.map(card).join(''):'<p class="maintenance-empty">✓<br>Nenhuma solicitação<br>nesta etapa.</p>'))+'</div></section>'}).join('')+'</div>';bindActions(box)}}
function whatsapp(r){const q=quotes(r),lines=['*'+r.number+' - COMPRAS MANUTENÇÃO*',r.description,'Solicitante: '+r.requester,'Quantidade: '+(r.quantity||'—')+' '+(r.unit||''),'Necessário até: '+d(r.neededDate),'Status: '+r.status];if(r.oc)lines.push('OC: '+r.oc);if(r.company)lines.push('Empresa: '+r.company);if(r.supplier)lines.push('Fornecedor: '+r.supplier);if(r.systemOrder)lines.push('Pedido: '+r.systemOrder);if(q.length)lines.push('Cotações: '+q.length);window.open('https://wa.me/?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener,noreferrer')}
function historyHtml(r){const h=r.history||[];return h.length?h.slice().reverse().map(x=>'<p><b>'+new Date(x.at).toLocaleString('pt-BR')+'</b> · '+Object.keys(x.changes||{}).join(', ')+'</p>').join(''):'<p>Sem histórico.</p>'}
function detail(r){selectedId=r.id;const q=quotes(r),m=meta(r);document.querySelector('#mn-detail').innerHTML='<section class="panel mn-detail"><div class="mn-detail-head"><div><strong>'+e(r.number)+'</strong><span class="mn-status">'+e(r.status)+'</span></div><div><button title="Editar solicitação" data-detail-edit>✏️ Editar</button><button title="Enviar pelo WhatsApp" class="wa" data-detail-wa>💬 WhatsApp</button>'+(nextStatus(r)?'<button class="advance" data-detail-advance>Avançar etapa →</button>':'')+'</div></div><div class="mn-flow">'+flow.map((s,i)=>'<span class="'+(s===r.status?'active ':'')+(flow.indexOf(r.status)>i?'done':'')+'"><i></i>'+e(s)+'</span>').join('')+'</div><div class="mn-detail-grid"><div class="mn-info"><h4>Informações gerais</h4><p><b>Descrição</b><br>'+e(r.description)+'</p><p><b>Solicitante</b><br>'+e(r.requester)+'</p><p><b>Responsável</b><br>'+e(r.buyer||'—')+'</p><p><b>Origem</b><br>'+e(r.origin)+(r.oc?' · OC '+e(r.oc):'')+'</p><p><b>Empresa do pedido</b><br>'+e(r.company||'—')+'</p><p><b>Equipamento</b><br>'+e(r.equipment||'—')+'</p><p><b>Necessário até</b><br>'+d(r.neededDate)+'</p><p><b>Quantidade</b><br>'+e(r.quantity||'—')+' '+e(r.unit||'')+'</p><p><b>Fornecedor</b><br>'+e(r.supplier||'—')+'</p><p><b>Valor</b><br>'+money(m.amount)+'</p><p><b>Pagamento</b><br>'+e(m.paymentTerms||'—')+'</p><p><b>Pedido</b><br>'+e(r.systemOrder||'—')+'</p></div><div class="mn-tabs"><div class="mn-tab-title">Cotações ('+q.length+')</div><div class="table-scroll"><table><thead><tr><th>Fornecedor</th><th>Valor</th><th>Prazo entrega</th><th>Condição</th><th>Observação</th><th>Ações</th></tr></thead><tbody>'+q.map((x,i)=>'<tr><td>'+e(x.supplier||'—')+'</td><td>'+money(x.amount)+'</td><td>'+e(x.delivery||'—')+'</td><td>'+e(x.payment||'—')+'</td><td>'+e(x.notes||'—')+'</td><td><button title="Editar cotação" class="mn-edit-quote" data-edit-quote="'+i+'">✏️</button></td></tr>').join('')+(q.length?'':'<tr><td colspan="6">Nenhuma cotação cadastrada.</td></tr>')+'</tbody></table></div><div class="mn-quote-actions"><button class="mn-add-quote" data-add-quote>＋ Adicionar cotação</button><button class="mn-compare-quotes" data-compare-quotes>⚖ Analisar cotações</button></div><div id="mn-quote-analysis"></div><details><summary>Histórico ('+(r.history||[]).length+')</summary>'+historyHtml(r)+'</details></div></div></section>';const z=document.querySelector('#mn-detail');z.scrollIntoView({behavior:'smooth',block:'start'});z.querySelector('[data-detail-edit]').onclick=()=>form(r);z.querySelector('[data-detail-wa]').onclick=()=>whatsapp(r);z.querySelector('[data-add-quote]').onclick=()=>quoteForm(r);z.querySelectorAll('[data-edit-quote]').forEach(b=>b.onclick=()=>quoteForm(r,Number(b.dataset.editQuote)));z.querySelector('[data-compare-quotes]').onclick=()=>analyzeQuotes(r);z.querySelector('[data-detail-advance]')?.addEventListener('click',async()=>{await saveRow(r,{status:nextStatus(r)});await load();detail(rows.find(x=>x.id===r.id))})}
function quoteNumber(v){const s=String(v??'').trim().replace(/\s/g,'');if(!s)return null;const normalized=s.includes(',')?s.replace(/\./g,'').replace(',','.'):s;const n=Number(normalized);return Number.isFinite(n)?n:null}
function deliveryDays(v){const m=String(v??'').match(/\d+/);return m?Number(m[0]):null}
function paymentScore(v){
  const text=String(v||'').toLowerCase().trim();
  if(!text)return {score:35,label:'Não informado'};
  if(/à vista|a vista|avista/.test(text))return {score:0,label:'À vista'};
  const nums=(text.match(/\d+/g)||[]).map(Number).filter(n=>Number.isFinite(n)&&n>0);
  if(!nums.length)return {score:35,label:text};
  const max=Math.max(...nums),installments=nums.length;
  const prazoScore=Math.min(100,(max/90)*100);
  const parcelaBonus=Math.min(25,Math.max(0,installments-1)*10);
  return {score:Math.min(100,Math.round(prazoScore+parcelaBonus)),label:text,max,installments};
}
function analyzeQuotes(r){
  const q=quotes(r),box=document.querySelector('#mn-quote-analysis');
  if(q.length<2){box.innerHTML='<div class="mn-analysis warn"><strong>⚠ Análise de cotações</strong><p>Cadastre pelo menos 2 cotações para comparar preço, entrega e pagamento.</p></div>';return}
  const data=q.map((x,i)=>({...x,_i:i,price:quoteNumber(x.amount),days:deliveryDays(x.delivery),pay:paymentScore(x.payment)}));
  const prices=data.filter(x=>x.price!=null),knownDays=data.filter(x=>x.days!=null&&x.days>0);
  const minPrice=prices.length?Math.min(...prices.map(x=>x.price)):null,minDays=knownDays.length?Math.min(...knownDays.map(x=>x.days)):null;
  const scored=data.map(x=>{
    const priceScore=minPrice!=null&&x.price!=null?(minPrice/x.price)*100:50;
    const deliveryScore=minDays!=null&&x.days!=null&&x.days>0?(minDays/x.days)*100:50;
    const score=priceScore*.35+deliveryScore*.20+x.pay.score*.45;
    return {...x,priceScore,deliveryScore,score};
  });
  const best=[...scored].sort((a,b)=>b.score-a.score)[0];
  const rows=scored.map(x=>'<tr class="'+(x._i===best._i?'best':'')+'"><td>'+e(x.supplier||'—')+'</td><td>'+money(x.price)+'</td><td>'+e(x.delivery||'A confirmar')+'</td><td>'+e(x.payment||'—')+'</td><td>'+x.priceScore.toFixed(0)+'</td><td>'+x.deliveryScore.toFixed(0)+'</td><td>'+x.pay.score.toFixed(0)+'</td><td><b>'+x.score.toFixed(0)+'%</b></td></tr>').join('');
  box.innerHTML='<div class="mn-analysis"><div class="mn-analysis-head"><div><span>RECOMENDAÇÃO DO SISTEMA</span><h4>✓ '+e(best.supplier||'Fornecedor')+'</h4><p>Entre as cotações cadastradas, '+e(best.supplier||'este fornecedor')+' apresenta a melhor relação considerando preço, prazo de entrega e condição de pagamento.</p></div><div class="mn-analysis-score"><strong>'+best.score.toFixed(0)+'</strong><span>Índice comparativo</span></div></div><div class="table-scroll"><table><thead><tr><th>Fornecedor</th><th>Preço total</th><th>Prazo entrega</th><th>Condição de pagamento</th><th>Preço (35%)</th><th>Prazo (20%)</th><th>Pagamento (45%)</th><th>Índice</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="mn-analysis-rule"><b>Critério:</b> preço 35% + prazo de entrega 20% + condição de pagamento 45%. No pagamento, à vista recebe 0 ponto; quanto maior o prazo e quanto mais parcelas, maior a pontuação. Prazo de entrega “a confirmar” recebe pontuação neutra até ser informado.</p><button class="mn-select-quote">🛒 Comprar com '+e(best.supplier||'fornecedor')+'</button></div>';
  box.querySelector('.mn-select-quote').onclick=async()=>{if(!confirm('Confirmar '+e(best.supplier||'fornecedor')+' como fornecedor escolhido?'))return;try{await saveRow(r,{supplier:best.supplier||r.supplier,status:'Pedido emitido'});await load();detail(rows.find(x=>x.id===r.id))}catch(err){alert(err.message)}};
  box.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function quoteForm(r,editIndex=null){
  const q=quotes(r),m=meta(r),host=document.querySelector('#mn-detail'),editing=editIndex!=null?q[editIndex]:null;
  host.querySelector('#mn-quote-editor')?.remove();
  const section=document.createElement('section');
  section.id='mn-quote-editor';section.className='panel maintenance-editor mn-quote-editor';
  section.innerHTML='<h3>'+(editing?'Editar cotação':'Adicionar cotação')+' · '+e(r.number)+'</h3><form id="qf"><div class="maintenance-fields"><label>Fornecedor<input name="supplier" required value="'+e(editing?.supplier||'')+'"></label><label>Valor (R$)<input name="amount" required inputmode="decimal" value="'+e(editing?.amount||'')+'" placeholder="Ex.: 1233,00"></label><label>Prazo de entrega<input name="delivery" value="'+e(editing?.delivery||'')+'" placeholder="Ex.: 7 dias"></label><label>Condição de pagamento<input name="payment" value="'+e(editing?.payment||'')+'" placeholder="Ex.: 28 dias"></label></div><label>Observação<textarea name="notes">'+e(editing?.notes||'')+'</textarea></label><div class="maintenance-actions"><button>Salvar cotação</button><button type="button" id="qc">Cancelar</button></div></form>';
  host.appendChild(section);const formEl=section.querySelector('#qf');section.querySelector('#qc').onclick=()=>section.remove();section.scrollIntoView({behavior:'smooth',block:'start'});
  formEl.onsubmit=async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(formEl)),newQuote={kind:'quote',...v},updated=[...q];if(editIndex==null)updated.push(newQuote);else updated[editIndex]=newQuote;const all=[...(m&&Object.keys(m).length?[m]:[]),...updated];try{await saveRow(r,{quotesJson:JSON.stringify(all)});await load();detail(rows.find(x=>x.id===r.id))}catch(err){alert(err.message)}};
}
function form(r){document.querySelector('#me').innerHTML='<section class="panel maintenance-editor"><h3>'+(r.id?'Editar '+e(r.number):'Nova solicitação')+'</h3><form id="mf"><div class="maintenance-fields"><label>Tipo<select name="type">'+opt(['Material','Serviço'],r.type||'Material')+'</select></label><label>Origem<select name="origin">'+opt(['OC','WhatsApp','Outro'],r.origin||'WhatsApp')+'</select></label><label>Solicitante<input name="requester" required value="'+e(r.requester||'')+'"></label><label>Responsável pela compra<input name="buyer" value="'+e(r.buyer||'')+'"></label><label>OC<input name="oc" value="'+e(r.oc||'')+'"></label><label>Empresa do pedido<select name="company"><option value="">Selecione</option>'+opt(['Colafix','Fixcol'],r.company||'')+'</select></label><label>Prioridade<select name="priority">'+opt(['Normal','Alta','Urgente'],r.priority||'Normal')+'</select></label><label>Equipamento / setor<input name="equipment" value="'+e(r.equipment||'')+'"></label><label>Quantidade<input name="quantity" value="'+e(r.quantity||'')+'"></label><label>UM<input name="unit" value="'+e(r.unit||'')+'"></label><label>Necessário até<input type="date" name="neededDate" value="'+e(r.neededDate||'')+'"></label><label>Status<select name="status">'+opt(sts,r.status||'Solicitado')+'</select></label><label>Fornecedor escolhido<input name="supplier" value="'+e(r.supplier||'')+'"></label><label>Pedido no sistema<input name="systemOrder" value="'+e(r.systemOrder||'')+'"></label><label>Entrega prometida<input type="date" name="promisedDate" value="'+e(r.promisedDate||'')+'"></label><label>Valor total (R$)<input name="amount" inputmode="decimal" value="'+e(meta(r).amount||'')+'"></label><label>Condição de pagamento<input name="paymentTerms" value="'+e(meta(r).paymentTerms||'')+'"></label><label>Data do pedido<input type="date" name="orderDate" value="'+e(meta(r).orderDate||'')+'"></label><label>Execução prevista<input type="date" name="serviceDate" value="'+e(meta(r).serviceDate||'')+'"></label></div><label>Material / serviço<textarea name="description" required>'+e(r.description||'')+'</textarea></label><div id="mw"></div><label>Observações<textarea name="notes">'+e(r.notes||'')+'</textarea></label><div class="maintenance-actions"><button>Salvar solicitação</button><button type="button" id="mc">Fechar</button></div></form></section>';const f=document.querySelector('#mf'),w=document.querySelector('#mw');const check=()=>{const terms=f.description.value.toLowerCase().split(' ').filter(x=>x.length>3),m=rows.filter(x=>x.id!==r.id&&!closed(x)&&terms.some(t=>x.description.toLowerCase().includes(t))).slice(0,3);w.innerHTML=m.length?'<div class="duplicate-warning"><strong>Possível solicitação duplicada</strong>'+m.map(x=>'<p>'+e(x.number)+' · '+e(x.description)+' · '+e(x.status)+'</p>').join('')+'</div>':''};f.description.oninput=check;check();document.querySelector('#mc').onclick=()=>document.querySelector('#me').innerHTML='';f.onsubmit=async x=>{x.preventDefault();const v=Object.fromEntries(new FormData(f));v.id=r.id;v.version=r.version;const oldQuotes=quotes(r);v.quotesJson=JSON.stringify([{kind:'commercial',amount:v.amount||'',paymentTerms:v.paymentTerms||'',orderDate:v.orderDate||'',serviceDate:v.serviceDate||''},...oldQuotes]);delete v.amount;delete v.paymentTerms;delete v.orderDate;delete v.serviceDate;try{await saveRow(r,v);await load()}catch(err){w.textContent=err.message}}}
